"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[9051],{2327:(e,t,i)=>{i.d(t,{A:()=>n});const n=i.p+"assets/images/ba_interview-5ccca58bed049d1a2b090d6448f0f97e.jpg"},4907:(e,t,i)=>{i.r(t),i.d(t,{assets:()=>l,contentTitle:()=>a,default:()=>c,frontMatter:()=>s,metadata:()=>n,toc:()=>d});var n=i(6188),o=i(4848),r=i(8453);const s={date:new Date("2022-02-06T19:05:00.000Z"),description:"Recently I was looking for a Junior Business Analyst to join my team. I considered candidates with little or no experience in IT. After I finalized my feedback for each candidate, I realized some missteps which occurred in a number of the interviews. Even though they seem to be obvious, it is important to highlight them and provide my suggestions.",slug:"tips-for-junior-ba-interview",tags:["Business Analysis"],title:"Pre-interview tips for Junior Business Analysts"},a="Pre-interview tips for Junior Business Analysts",l={authorsImageUrls:[]},d=[{value:"Invest your efforts in formatting and language of your test/diploma project",id:"invest-your-efforts-in-formatting-and-language-of-your-testdiploma-project",level:2},{value:"Be able to explain the requirements documentation approaches you use",id:"be-able-to-explain-the-requirements-documentation-approaches-you-use",level:2},{value:"If your diploma project is group work, make your contribution clear",id:"if-your-diploma-project-is-group-work-make-your-contribution-clear",level:2},{value:"Write your diploma project in English (for non-native speakers)",id:"write-your-diploma-project-in-english-for-non-native-speakers",level:2},{value:"Study different sources of knowledge",id:"study-different-sources-of-knowledge",level:2},{value:"When you send files, don&#39;t use proprietary file formats",id:"when-you-send-files-dont-use-proprietary-file-formats",level:2},{value:"Do your homework",id:"do-your-homework",level:2},{value:"As conclusion",id:"as-conclusion",level:2},{value:"References",id:"references",level:2},{value:"Change history",id:"change-history",level:2}];function u(e){const t={em:"em",h2:"h2",img:"img",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"Cover",src:i(2327).A+"",width:"1280",height:"929"})}),"\n",(0,o.jsx)(t.p,{children:"Recently I was looking for a Junior Business Analyst to join my team. I considered candidates with little or no experience in IT. And that was an excellent experience for me. For the first time in my career I:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsx)(t.li,{children:"wholly owned job requirements for the position"}),"\n",(0,o.jsx)(t.li,{children:"made a final decision to hire someone or not"}),"\n",(0,o.jsx)(t.li,{children:"was not doing the tech part of an interview"}),"\n",(0,o.jsx)(t.li,{children:"interviewed Junior-level specialists."}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"It is different from interviewing a Middle or Senior BA. You can discuss various topics with more experienced professionals: practical cases, challenges, techniques, recent articles, etc. But that is hardly applicable for the Juniors as they can share only their background and knowledge of theory with the ability to apply that in practice, at the very least."}),"\n",(0,o.jsx)(t.p,{children:"The main proof of their ability is a diploma project if they have previously finished some business analysis courses. Another option is a test task or even a pet project. And be well prepared for an interview, of course."}),"\n",(0,o.jsx)(t.p,{children:"I was not hosting a part with Business Analysis questions, so I focused on the written evidence and carefully listened to the interviewee. After I finalized my feedback for each candidate, I realized some missteps which occurred in a number of the interviews. Even though they seem to be obvious, it is important to highlight them and provide my suggestions."}),"\n",(0,o.jsx)(t.h2,{id:"invest-your-efforts-in-formatting-and-language-of-your-testdiploma-project",children:"Invest your efforts in formatting and language of your test/diploma project"}),"\n",(0,o.jsx)(t.p,{children:"Whether it is a diploma project from BA courses or a practical task given to you before an interview: you must do your best."}),"\n",(0,o.jsx)(t.p,{children:"The first impression is essential. You can provide a better experience for the readers, which is your advantage over other candidates."}),"\n",(0,o.jsx)(t.p,{children:"Many years ago, I was helping my mentor with reviewing the practical tasks of candidates who applied for a Junior BA position. I was shocked when he refused to read a document further without a table of contents, so a candidate missed the chance. The mentor did not care how good the work might be. That was a crucial criterion for him to stop wasting time and proceed to the next candidate."}),"\n",(0,o.jsx)(t.p,{children:"From my perspective, it is unfair not to give a chance to a specification with some formatting issues. But that situation states that you never know who will look at your specification document and what their expectations are."}),"\n",(0,o.jsx)(t.h2,{id:"be-able-to-explain-the-requirements-documentation-approaches-you-use",children:"Be able to explain the requirements documentation approaches you use"}),"\n",(0,o.jsx)(t.p,{children:'"We did that because our mentor told us" - is a wrong answer about the decision to proceed with user stories instead of use cases in your test/diploma project. You should be ready to justify a used approach considering its advantages and disadvantages.'}),"\n",(0,o.jsx)(t.p,{children:"An interviewer can ask you to compare two approaches and express your opinion on which is better. The fun part is that there is no correct answer; in Business Analysis, some things may work depending on a project context. Just share your opinion, even if you have little experience using both. That is a tricky way to test your current understanding of those techniques."}),"\n",(0,o.jsx)(t.h2,{id:"if-your-diploma-project-is-group-work-make-your-contribution-clear",children:"If your diploma project is group work, make your contribution clear"}),"\n",(0,o.jsx)(t.p,{children:"Business Analysis course students tend to write their diploma projects in a group of 3-5 persons. Nothing wrong with that. But for me, that makes assessing a candidate's skills problematic."}),"\n",(0,o.jsx)(t.p,{children:'"We did all the stuff together" - a lousy answer to a question on how you organized work on the diploma project. That gives me no clue why I should hire you instead of your group mates.'}),"\n",(0,o.jsx)(t.p,{children:"Working in a group of BAs is a valuable skill, but that must be a well-organized process with a clear contribution from each peer. You'd better sign the parts you made with your name and be prepared to explain others' parts as your own."}),"\n",(0,o.jsx)(t.h2,{id:"write-your-diploma-project-in-english-for-non-native-speakers",children:"Write your diploma project in English (for non-native speakers)"}),"\n",(0,o.jsx)(t.p,{children:"If you plan to start your BA career in an international company or company with international customers, write your diploma project in English. As a Junior BA, you are unlikely to be involved much in communication with stakeholders from the beginning. Your time to shine will come a bit later."}),"\n",(0,o.jsx)(t.p,{children:"More time you will spend on specifying and documenting requirements. You'd better provide additional proof of your written English."}),"\n",(0,o.jsx)(t.h2,{id:"study-different-sources-of-knowledge",children:"Study different sources of knowledge"}),"\n",(0,o.jsx)(t.p,{children:"It is painful to hear how a prospective candidate fails to explain the meaning of stakeholder requirements and their place in the requirements hierarchy. I think that happens because most BA students read only the Wiegers*, in which stakeholder requirements are not considered a subject of the requirements structure and are implied to be a part of the business requirements. Wieger's definition is fine, but you'd better study BACCM** by IIBA (free) and learn the modern industry-agreed standard."}),"\n",(0,o.jsx)(t.h2,{id:"when-you-send-files-dont-use-proprietary-file-formats",children:"When you send files, don't use proprietary file formats"}),"\n",(0,o.jsx)(t.p,{children:'One candidate sent an "eap" file as a documented example to prove their BA skills. Once I got that file from recruiters, I realized I lacked the software to open it on my laptop. I quickly googled that "eap" is an extension for Enterprise Architect files. It is a well-known industry tool, but neither I have worked with it nor my organization. So what will my next steps be? To install Enterprise Architect, register, start a 30 days trial, learn how to use it, and finally open that file for a review, I guess.'}),"\n",(0,o.jsx)(t.p,{children:"But that never happened. I switched to an assessment of other candidates, and that file's content remains a mystery."}),"\n",(0,o.jsx)(t.p,{children:"You can blame me, but I value my time and want other parties to respect it. Please use standard file formats (like PDF, docx, etc.) or something that can be opened in a web browser (without mandatory sign-up and providing my credit card information). Remember, as a Junior specialist, you compete for a job with many other talented people. And you are not in a position to demand more time than the others. Deal with that."}),"\n",(0,o.jsx)(t.h2,{id:"do-your-homework",children:"Do your homework"}),"\n",(0,o.jsx)(t.p,{children:"Not having questions for an interview is a bad sign for a hiring manager. Please prepare some questions about the company, the project/product, the team structure, your future responsibilities, organization processes, etc. Be bold and ask any relevant question which comes to your mind."}),"\n",(0,o.jsx)(t.p,{children:"If it is a product-oriented company, then study any available marketing materials about its products and value proposition you find on the Internet. Nowadays, organizations are largely investing in content marketing, so it is easy to find some hooks to help you formulate your questions."}),"\n",(0,o.jsx)(t.h2,{id:"as-conclusion",children:"As conclusion"}),"\n",(0,o.jsx)(t.p,{children:"If you have not got a job offer after an interview or your application hasn't even been considered, that does not mean you are a terrible business analyst. In 80% of cases, your skills do not fit a particular position. In the other 20%, you might not have done your homework, the interview went surprisingly bad, or it was a combination of these factors."}),"\n",(0,o.jsx)(t.p,{children:"Consider rejection as a blessing and keep going. Seek, and you shall find."}),"\n",(0,o.jsx)(t.h2,{id:"references",children:"References"}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.em,{children:"*Karl Wiegers and Joy Beatty \u201cSoftware Requirements\u201d, 3rd edition"})}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.em,{children:"**Business Analysis Core Concept Model"})}),"\n",(0,o.jsxs)("small",{children:["Image from ",(0,o.jsx)("a",{href:"https://www.vecteezy.com/free-vector/cv",children:"Cv Vectors by Vecteezy"})]}),"\n",(0,o.jsx)(t.h2,{id:"change-history",children:"Change history"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsx)(t.li,{children:"2022-02-06: Initial version published"}),"\n",(0,o.jsx)(t.li,{children:"2023-05-10: Second revision published"}),"\n"]})]})}function c(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},6188:e=>{e.exports=JSON.parse('{"permalink":"/blog/tips-for-junior-ba-interview","source":"@site/blog/2022/tips-for-junior-ba-interview.md","title":"Pre-interview tips for Junior Business Analysts","description":"Recently I was looking for a Junior Business Analyst to join my team. I considered candidates with little or no experience in IT. After I finalized my feedback for each candidate, I realized some missteps which occurred in a number of the interviews. Even though they seem to be obvious, it is important to highlight them and provide my suggestions.","date":"2022-02-06T19:05:00.000Z","tags":[{"inline":true,"label":"Business Analysis","permalink":"/blog/tags/business-analysis"}],"readingTime":6.09,"hasTruncateMarker":true,"authors":[],"frontMatter":{"date":"2022-02-06T19:05:00.000Z","description":"Recently I was looking for a Junior Business Analyst to join my team. I considered candidates with little or no experience in IT. After I finalized my feedback for each candidate, I realized some missteps which occurred in a number of the interviews. Even though they seem to be obvious, it is important to highlight them and provide my suggestions.","slug":"tips-for-junior-ba-interview","tags":["Business Analysis"],"title":"Pre-interview tips for Junior Business Analysts"},"unlisted":false,"prevItem":{"title":"Product Manager: Year One","permalink":"/blog/product-manager-year-one"},"nextItem":{"title":"Definition of API requirements","permalink":"/blog/definition-of-api-requirements"}}')},8453:(e,t,i)=>{i.d(t,{R:()=>s,x:()=>a});var n=i(6540);const o={},r=n.createContext(o);function s(e){const t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);